</script>
<template><div class="demo-shell"><header class="demo-top"><strong>Metteur</strong><span class="preview-badge">UI preview · R1</span><button class="icon-btn" aria-label="Switch theme" @click="theme"><Sun v-if="dark" :size="17"/><Moon v-else :size="17"/></button></header><div class="demo-body"><ActivityRail :items="items" :active="active" storage-key="metteur.preview.navigation.r1" @select="active=$event;query=''" @settings="notify('Existing Settings stays pinned')"/><main class="demo-main"><div class="page-heading"><div class="title-row"><h1>{{title}}</h1><button v-if="help[active]" class="icon-btn help" :aria-label="`About ${title}`" :title="help[active]"><Info :size="17"/></button></div><div class="heading-actions"><button v-if="active==='tasks'" class="btn btn-primary" @click="notify('The exact goal, time and budget confirmation is retained')"><Plus :size="15"/>New task</button><button v-if="active==='schedules'" class="btn btn-primary" @click="notify('Choose a saved waiting task before creating a plan')"><Plus :size="15"/>New schedule</button><button class="icon-btn" aria-label="Refresh" title="Refresh" @click="notify('Preview fixtures refreshed')"><RefreshCw :size="16"/></button></div></div>
